/// Convert between hexadecimal and standard Base64 text, in either
/// direction, validating the input.
/// If value starts with "hex:", the rest must be an even number (possibly zero)
/// of hex digits 0-9, a-f, A-F, read in pairs as bytes; return "b64:" followed
/// by the standard Base64 encoding of those bytes: alphabet A-Z a-z 0-9 + /
/// (values 0 to 63 in that order), each 3 bytes become 4 characters, and a final
/// group of 1 or 2 bytes is padded with "==" or "=" to 4 characters.
/// If value starts with "b64:", the rest must be canonical Base64: a length that
/// is a multiple of 4 (possibly zero), only alphabet characters, except that the
/// last group may end in "=" or "==" (padding nowhere else, never 3 or 4 "="),
/// and the bits that the padding discards must be zero (so "QQ==" is valid but
/// "QR==" is not). Return "hex:" followed by the decoded bytes as lowercase hex,
/// two digits per byte.
/// For every other input (another or uppercase prefix, an odd number of hex
/// digits, a bad character, whitespace, wrong length, misplaced padding,
/// non-zero discarded bits) return the string "invalid".
/// >>> base64_convert("hex:4d616e")
/// String::from("b64:TWFu")
/// >>> base64_convert("b64:TWE=")
/// String::from("hex:4d61")
fn base64_convert(value: &str) -> String {
    let invalid = String::from("invalid");
    if let Some(rest) = value.strip_prefix("hex:") {
        return match hex_bytes(rest) {
            Some(data) => format!("b64:{}", b64_encode(&data)),
            None => invalid,
        };
    }
    if let Some(rest) = value.strip_prefix("b64:") {
        return match b64_decode(rest) {
            Some(data) => format!("hex:{}", data.iter().map(|b| format!("{:02x}", b)).collect::<String>()),
            None => invalid,
        };
    }
    invalid
}

const ABC: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

fn hex_bytes(s: &str) -> Option<Vec<u32>> {
    let cs: Vec<char> = s.chars().collect();
    if cs.len() % 2 != 0 {
        return None;
    }
    let mut out = Vec::new();
    for pair in cs.chunks(2) {
        let hi = pair[0].to_digit(16)?;
        let lo = pair[1].to_digit(16)?;
        out.push(hi * 16 + lo);
    }
    Some(out)
}

fn b64_encode(data: &[u32]) -> String {
    let mut out = String::new();
    for chunk in data.chunks(3) {
        let n = chunk.len();
        let get = |k: usize| if k < n { chunk[k] } else { 0 };
        let v = (get(0) << 16) | (get(1) << 8) | get(2);
        out.push(ABC[(v >> 18) as usize] as char);
        out.push(ABC[((v >> 12) & 63) as usize] as char);
        out.push(if n > 1 { ABC[((v >> 6) & 63) as usize] as char } else { '=' });
        out.push(if n > 2 { ABC[(v & 63) as usize] as char } else { '=' });
    }
    out
}

fn b64_decode(s: &str) -> Option<Vec<u32>> {
    let cs: Vec<char> = s.chars().collect();
    if cs.len() % 4 != 0 {
        return None;
    }
    let mut out = Vec::new();
    for (g, group) in cs.chunks(4).enumerate() {
        let mut pad = 0;
        if (g + 1) * 4 == cs.len() && group[3] == '=' {
            pad = if group[2] == '=' { 2 } else { 1 };
        }
        let mut v: u32 = 0;
        for &c in &group[..4 - pad] {
            // also rejects '=' anywhere but the final padding
            let d = ABC.iter().position(|&a| a as char == c)? as u32;
            v = v * 64 + d;
        }
        v <<= 6 * pad;
        // bits dropped by the padding must be zero
        if (pad == 1 && v & 0xFF != 0) || (pad == 2 && v & 0xFFFF != 0) {
            return None;
        }
        let bytes = [v >> 16, (v >> 8) & 0xFF, v & 0xFF];
        out.extend_from_slice(&bytes[..3 - pad]);
    }
    Some(out)
}
